// Normaliza el payload de WhatsApp Cloud API a { telefono, nombre, texto }.
// El trigger nativo entrega el objeto `value` de Meta; si alguien reemplaza
// el trigger por un webhook generico, el payload llega bajo .body.
const j = $json;
const value = j.body?.entry?.[0]?.changes?.[0]?.value ?? j.entry?.[0]?.changes?.[0]?.value ?? j;

const message = value.messages?.[0] ?? {};
const contact = value.contacts?.[0] ?? {};

const telefono = message.from ?? contact.wa_id ?? '';
const nombre = contact.profile?.name ?? null;

// Solo procesamos texto. Audio/imagen/documento se marcan para que el
// agente pida al cliente que escriba, en vez de romper el flujo.
const tipo = message.type ?? 'desconocido';
const texto = tipo === 'text'
  ? (message.text?.body ?? '')
  : `[El cliente envio un mensaje de tipo "${tipo}" que no puedo leer]`;

return {
  json: {
    telefono,
    nombre,
    texto,
    tipo,
    es_texto: tipo === 'text',
    wa_message_id: message.id ?? null
  }
};

// Normaliza el payload del Chat Trigger a la MISMA forma que produce
// 'Extraer Mensaje' para WhatsApp: { telefono, nombre, texto }.
// Asi el resto del flujo (upsert de lead, memoria, agente) es identico
// en los dos canales y lo que se prueba aqui es lo que corre en produccion.
//
// El sessionId del chat hace las veces de telefono: es la clave de sesion
// de la memoria y la identidad del lead. Se prefija para que un lead de
// prueba nunca colisione con un telefono real de WhatsApp.
const j = $json;
const sessionId = j.sessionId ?? 'sin-sesion';
const texto = j.chatInput ?? j.message ?? '';

return {
  json: {
    telefono: `test-${sessionId}`,
    nombre: 'Cliente de Prueba',
    texto,
    tipo: 'text',
    es_texto: true,
    wa_message_id: null
  }
};
